function crewCover(skills, volunteers) {
  const full = (1 << skills) - 1;
  let best = Infinity;
  const choose = (index, covered, count) => {
    if (count >= best) return;
    if (covered === full) {
      best = count;
      return;
    }
    if (index === volunteers.length) return;
    choose(index + 1, covered | volunteers[index], count + 1);
    choose(index + 1, covered, count);
  };
  choose(0, 0, 0);
  return best === Infinity ? -1 : best;
}

